using Aspire.Hosting.Testing;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.Extensions.DependencyInjection;

namespace MyApp.Evaluation;

[TestClass]
public class ChatEvaluationTests
{
    private static DistributedApplicationTestingBuilder _appHost = null!;
    private static DistributedApplication _app = null!;
    private static IChatClient _chatClient = null!;
    private static IChatClient _evaluatorClient = null!;

    [ClassInitialize]
    public static async Task ClassInitialize(TestContext context)
    {
        _appHost = await DistributedApplicationTestingBuilder.CreateAsync<Projects.MyApp_AppHost>();
        _app = await _appHost.BuildAsync();
        await _app.StartAsync();

        _chatClient = _app.Services.GetRequiredService<IChatClient>();
        _evaluatorClient = _chatClient;
    }

    [ClassCleanup]
    public static async Task ClassCleanup()
    {
        await _app.DisposeAsync();
    }

    [TestMethod]
    public async Task Chat_ReturnsRelevantResponse()
    {
        // Arrange
        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "What is the capital of France?")
        };

        // Act
        var response = await _chatClient.GetResponseAsync(messages);

        // Assert — basic sanity check
        Assert.IsNotNull(response);
        Assert.IsTrue(response.Messages.Count > 0);
        Assert.IsTrue(
            response.Messages.Any(m => m.Text?.Contains("Paris", StringComparison.OrdinalIgnoreCase) == true),
            "Expected the response to mention Paris.");
    }

    [TestMethod]
    public async Task Chat_EvaluateRelevanceAndCoherence()
    {
        // Arrange
        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "Explain how photosynthesis works in two sentences.")
        };

        // Act
        var response = await _chatClient.GetResponseAsync(messages);
        var responseText = string.Join(" ", response.Messages.Select(m => m.Text));

        // Evaluate
        var evaluators = new IEvaluator[]
        {
            new RelevanceTruthAndCompletenessEvaluator(),
            new CoherenceEvaluator(),
        };

        var chatContext = new ChatContext(messages, response.Messages);

        foreach (var evaluator in evaluators)
        {
            var result = await evaluator.EvaluateAsync(chatContext, _evaluatorClient);
            foreach (var metric in result)
            {
                Assert.IsTrue(
                    metric.Value is NumericMetricValue numericValue && numericValue.Value >= 3,
                    $"Metric '{metric.Key}' scored below threshold: {metric.Value}");
            }
        }
    }

    [TestMethod]
    public async Task Chat_EvaluateGroundedness()
    {
        // Arrange
        var context = "The Eiffel Tower is located in Paris, France. It was built in 1889.";
        var messages = new List<ChatMessage>
        {
            new(ChatRole.System, $"Answer based on this context: {context}"),
            new(ChatRole.User, "When was the Eiffel Tower built?")
        };

        // Act
        var response = await _chatClient.GetResponseAsync(messages);

        // Evaluate groundedness
        var evaluator = new GroundednessEvaluator();
        var chatContext = new ChatContext(messages, response.Messages);

        var result = await evaluator.EvaluateAsync(chatContext, _evaluatorClient);
        foreach (var metric in result)
        {
            Assert.IsTrue(
                metric.Value is NumericMetricValue numericValue && numericValue.Value >= 3,
                $"Groundedness metric '{metric.Key}' scored below threshold: {metric.Value}");
        }
    }
}

